<?php
namespace Database\Seeders;
use App\Models\Category;use App\Models\Product;use App\Models\Setting;use App\Models\User;use App\Models\DeliveryZone;use App\Models\HeroSlide;use Illuminate\Database\Seeder;use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder {public function run():void{
User::updateOrCreate(['email'=>env('ADMIN_EMAIL','shagurhd@gmail.com')],['name'=>'Aesthetic Store Admin','password'=>Hash::make(env('ADMIN_PASSWORD','ChangeThisStrongPassword123!')),'is_admin'=>true,'admin_role'=>'owner']);
$cats=[];foreach(['Home & Lifestyle','Gadgets','Beauty & Personal Care','Kitchen & Dining','Accessories'] as $i=>$name){$cats[$name]=Category::firstOrCreate(['slug'=>strtolower(str_replace([' & ',' '],['-','-'],$name))],['name'=>$name,'sort_order'=>$i+1,'is_active'=>true]);}
Setting::updateOrCreate(['key'=>'hero_eyebrow'],['value'=>'TRENDING NOW']);Setting::updateOrCreate(['key'=>'hero_title'],['value'=>'Discover Products You’ll Love']);Setting::updateOrCreate(['key'=>'hero_subtitle'],['value'=>'Shop the latest trending imported products, curated for modern lifestyles.']);Setting::updateOrCreate(['key'=>'hero_button_text'],['value'=>'Shop Now']);Setting::updateOrCreate(['key'=>'hero_button_url'],['value'=>'/shop']);Setting::updateOrCreate(['key'=>'support_phone'],['value'=>env('STORE_PHONE','01550720798')]);Setting::updateOrCreate(['key'=>'support_email'],['value'=>env('STORE_EMAIL','support@aestheticstore.bd')]);Setting::updateOrCreate(['key'=>'facebook_url'],['value'=>'']);Setting::updateOrCreate(['key'=>'address'],['value'=>'Dhaka, Bangladesh']);
foreach(['Dhaka'=>80,'Gazipur'=>110,'Narayanganj'=>110,'Chattogram'=>130,'Cumilla'=>130,'Sylhet'=>130,'Rajshahi'=>130,'Khulna'=>130,'Barishal'=>130,'Rangpur'=>130,'Mymensingh'=>130] as $district=>$charge) DeliveryZone::firstOrCreate(['district'=>$district],['charge'=>$charge,'is_active'=>true]);
if(HeroSlide::count()===0) HeroSlide::create(['eyebrow'=>'TRENDING NOW','title'=>'Discover Products You’ll Love','subtitle'=>'Shop useful, trendy Chinese imported products curated for Bangladesh.','button_text'=>'Shop Now','button_url'=>'/shop','sort_order'=>1,'is_active'=>true]);
if(Product::count()===0){Product::create(['category_id'=>$cats['Gadgets']->id,'name'=>'Mini Rechargeable Fan','slug'=>'mini-rechargeable-fan','sku'=>'AS-FAN-001','short_description'=>'Portable rechargeable mini fan for desk, travel and daily use.','description'=>'Compact Chinese imported rechargeable fan with simple controls and a lightweight body.','price'=>1290,'compare_price'=>1490,'stock'=>25,'is_active'=>true,'is_featured'=>true]);Product::create(['category_id'=>$cats['Home & Lifestyle']->id,'name'=>'LED Motion Sensor Light','slug'=>'led-motion-sensor-light','sku'=>'AS-LED-001','short_description'=>'Rechargeable motion sensor light for wardrobe, hallway and kitchen.','price'=>890,'compare_price'=>1090,'stock'=>40,'is_active'=>true,'is_featured'=>true]);}
}}
